<template><BtgPageContainer as="section" class="community-page" aria-labelledby="thread-title"><RouterLink :to="communityPath(courseId())" class="community-page__back">Back to discussions</RouterLink><div v-if="state.kind==='loading'" role="status"><h1 id="thread-title">Loading discussion…</h1></div><div v-else-if="state.kind==='missing'" class="community-page__empty"><h1 id="thread-title">Discussion unavailable</h1><p>This discussion is not available.</p></div><div v-else-if="state.kind==='unavailable'" role="alert"><h1 id="thread-title">Discussion unavailable</h1><p>We couldn’t load this discussion right now.</p><BtgButton variant="secondary" @click="load">Try again</BtgButton></div><template v-else><h1 id="thread-title" ref="heading" tabindex="-1">{{ state.thread.title }}</h1><ol class="community-posts"><li v-for="post in state.thread.posts" :key="post.postId"><article><p class="community-posts__meta">Participant · <time :datetime="post.createdAt">{{ formatDate(post.createdAt) }}</time></p><p class="community-posts__body">{{ post.body }}</p></article></li></ol><form class="community-form" @submit.prevent="reply"><h2>Reply</h2><label for="community-reply">Message</label><textarea id="community-reply" v-model="body" required maxlength="20000" rows="5" :disabled="replying"/><p v-if="error" class="community-error" role="alert">{{ error }}</p><p class="sr-only" aria-live="polite">{{ status }}</p><BtgButton type="submit" :disabled="replying">{{ replying?'Replying…':'Reply' }}</BtgButton></form></template></BtgPageContainer></template>
<script setup lang="ts">
import { onBeforeUnmount,ref,watch } from 'vue';import { useRoute } from 'vue-router';import { APIProblemError } from '../api/client';import BtgButton from '../components/BtgButton.vue';import BtgPageContainer from '../components/BtgPageContainer.vue';import { communityPath,createCommunityPost,getCommunityThread,type CommunityThread } from '../courses/community'
type State={kind:'loading'}|{kind:'missing'}|{kind:'unavailable'}|{kind:'ready',thread:CommunityThread};const route=useRoute(),state=ref<State>({kind:'loading'}),body=ref(''),error=ref(''),status=ref(''),replying=ref(false),heading=ref<HTMLElement|null>(null);let active=true,generation=0;const courseId=()=>typeof route.params.courseId==='string'?route.params.courseId:'';const threadId=()=>typeof route.params.threadId==='string'?route.params.threadId:'';watch([()=>route.params.courseId,()=>route.params.threadId],()=>{void load()},{immediate:true});onBeforeUnmount(()=>{active=false;generation++});async function load(){const course=courseId(),thread=threadId(),request=++generation;state.value={kind:'loading'};try{const value=await getCommunityThread(course,thread);if(!active||request!==generation||course!==courseId()||thread!==threadId())return;state.value={kind:'ready',thread:value}}catch(error){if(active&&request===generation)state.value=error instanceof APIProblemError&&error.status===404?{kind:'missing'}:{kind:'unavailable'}}}async function reply(){if(replying.value)return;replying.value=true;error.value='';try{const post=await createCommunityPost(courseId(),threadId(),body.value);if(state.value.kind==='ready'){state.value={kind:'ready',thread:{...state.value.thread,posts:[...state.value.thread.posts,post],postTotal:state.value.thread.postTotal+1}};body.value='';status.value='Reply posted.'}}catch(cause){if(cause instanceof APIProblemError&&cause.problem?.code==='community_disabled'){error.value='Discussions were disabled. Your message has not been sent.'}else error.value='Your reply could not be posted. Please try again.'}finally{replying.value=false}}function formatDate(value:string){return new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
</script>
